"""Regenerates the REVERSE-direction ``hpke-hybrid-v1`` interop golden.

``hybrid_reverse_vector.json`` is a payload sealed by *Python* (libcrux ML-KEM
encaps) for the *TypeScript* stack (``@noble/post-quantum``) to open.

``generate_hybrid_vectors.mjs`` proves the forward direction (TS seals, Python
opens). This proves the other one, which ML-KEM makes a genuinely distinct code
path: encapsulation and decapsulation are different operations, so a libcrux
ciphertext-encoding quirk would be invisible to a test that only ever asks noble
to *produce* the ciphertext. ``verify_hybrid_reverse.mjs`` is the noble side; the
Python side is ``test_hybrid.py::TestReverseInterop``.

Run from rine-sdk/ (the SDK's ``rine`` must be importable — see the isolated
sdkvenv the e2e/CI harness builds)::

    python tests/fixtures/generate_hybrid_reverse_vector.py \\
        > tests/fixtures/hybrid_reverse_vector.json

Only regenerate when the wire format deliberately changes.
"""

from __future__ import annotations

import json

from rine._crypto.hybrid import seal
from rine._crypto.keys import generate_agent_keys
from rine._utils import to_base64url

PLAINTEXT = b"post-quantum hello sealed by Python for TypeScript to open"
AAD = b"rine.v1.reverse-aad-probe"


def main() -> None:
    """Seal the golden with a fresh recipient key and print it as JSON."""
    recipient = generate_agent_keys()
    assert recipient.pq_encryption is not None

    payload = seal(
        recipient.encryption.public_key,
        recipient.pq_encryption.public_key,
        PLAINTEXT,
    )
    aad_payload = seal(
        recipient.encryption.public_key,
        recipient.pq_encryption.public_key,
        PLAINTEXT,
        AAD,
    )

    print(
        json.dumps(
            {
                "_comment": (
                    "Generated by tests/fixtures/generate_hybrid_reverse_vector.py. "
                    "Python-sealed (libcrux ML-KEM encaps); opened by noble in "
                    "verify_hybrid_reverse.mjs. Do not hand-edit."
                ),
                "recipient_encryption_private_key": to_base64url(recipient.encryption.private_key),
                "recipient_pq_private_key": to_base64url(recipient.pq_encryption.private_key),
                "plaintext": PLAINTEXT.decode(),
                "encrypted_payload": to_base64url(payload),
                "aad": to_base64url(AAD),
                "aad_payload": to_base64url(aad_payload),
            },
            indent=2,
        )
    )


if __name__ == "__main__":
    main()
